<?php get_header(); ?><main id="main" class="page-main"><div id="top"></div><?php while(have_posts()):the_post(); ?><header class="page-heading container"><div class="page-heading-copy"><span class="eyebrow"><?php echo esc_html(gopa_text('page_prefix')); ?> / <?php the_title(); ?></span><h1><?php echo esc_html(rtrim(get_the_title(),'.')); ?><span class="gold">.</span></h1><?php if(has_excerpt()): ?><p class="page-intro"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?></div><?php if(has_post_thumbnail()): ?><figure class="page-cover<?php echo get_post_field('post_name',get_the_ID())==='about-us'?' page-cover-team':''; ?>"><?php the_post_thumbnail('large',['loading'=>'eager']); ?></figure><?php endif; ?></header><div class="container page-content"><?php the_content(); ?></div><?php endwhile; ?></main><?php get_footer(); ?>
